"""Execute the compatibility transform and its generated bytecode on a native JVM."""
from pathlib import Path
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]
PACKAGE = 'com.stonytark.usefultoolsmod.compat.client'


class ForgeDirectionCompatibilityTests(unittest.TestCase):
    def test_restored_order_is_cached_immutable_and_existing_hook_unchanged(self):
        cache = Path.home() / '.gradle/caches/modules-2/files-2.1'
        jars = [next((cache / group / artifact / version).glob('*/' + artifact + '-' + version + '.jar'))
                for group, artifact, version in [('org.ow2.asm', 'asm', '9.6'),
                                                ('org.ow2.asm', 'asm-tree', '9.6'),
                                                ('org.spongepowered', 'mixin', '0.8.5')]]
        fixture = """package net.minecraft.core;
public final class Direction {
 public static final Direction NORTH = new Direction(), SOUTH = new Direction(),
 WEST = new Direction(), EAST = new Direction(), UP = new Direction(), DOWN = new Direction();
 public enum Plane { HORIZONTAL, VERTICAL;
  public java.util.stream.Stream<Direction> stream() {
   return this == HORIZONTAL ? java.util.stream.Stream.of(NORTH, EAST, SOUTH, WEST)
                            : java.util.stream.Stream.of(UP, DOWN);
  }
 }
}
"""
        runner = """package com.stonytark.usefultoolsmod.compat.client;
import java.nio.file.*;
import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
public final class CompatibilityTest {
 public static void main(String[] args) throws Exception {
  Path classFile = Path.of(args[0]);
  ClassNode node = new ClassNode(); new ClassReader(Files.readAllBytes(classFile)).accept(node, 0);
  ForgeDirectionCompatibilityPlugin.restoreUpdateOrder(node);
  int fields = node.fields.size(), methods = node.methods.size();
  ForgeDirectionCompatibilityPlugin.restoreUpdateOrder(node);
  if (fields != node.fields.size() || methods != node.methods.size()) throw new AssertionError("Not idempotent");
  ClassWriter writer = new ClassWriter(0); node.accept(writer); Files.write(classFile, writer.toByteArray());
  Class<?> direction = Class.forName("net.minecraft.core.Direction");
  var getter = direction.getMethod("getUpdateOrder"); Object first = getter.invoke(null);
  if (first != getter.invoke(null)) throw new AssertionError("Not cached");
  List<?> order = (List<?>) first; String[] names = {"NORTH", "EAST", "SOUTH", "WEST", "UP", "DOWN"};
  if (order.size() != names.length) throw new AssertionError("Incomplete order");
  for (int i = 0; i < names.length; i++)
   if (order.get(i) != direction.getField(names[i]).get(null)) throw new AssertionError("Wrong order");
  try { order.clear(); throw new AssertionError("Mutable order"); } catch (UnsupportedOperationException expected) { }
  ClassNode nativeNode = new ClassNode(); new ClassReader(Files.readAllBytes(classFile)).accept(nativeNode, 0);
  ClassWriter before = new ClassWriter(0); nativeNode.accept(before);
  ForgeDirectionCompatibilityPlugin.restoreUpdateOrder(nativeNode);
  ClassWriter after = new ClassWriter(0); nativeNode.accept(after);
  if (!Arrays.equals(before.toByteArray(), after.toByteArray())) throw new AssertionError("Changed native hook");
 }
}
"""
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            sources = []
            for name, source in [('net/minecraft/core/Direction.java', fixture),
                                  ('CompatibilityTest.java', runner)]:
                path = root / name; path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(source); sources.append(path)
            sources.append(ROOT / '1.21.1/forge/src/main/java' / PACKAGE.replace('.', '/')
                           / 'ForgeDirectionCompatibilityPlugin.java')
            classpath = ':'.join(map(str, jars))
            subprocess.run(['/usr/lib/jvm/java-21-openjdk/bin/javac', '--release', '21',
                            '-proc:none', '-Xlint:all', '-Werror', '-cp', classpath,
                            '-d', str(root), *map(str, sources)], check=True, capture_output=True)
            subprocess.run(['/usr/lib/jvm/java-21-openjdk/bin/java', '-Xverify:all',
                            '-cp', str(root) + ':' + classpath, PACKAGE + '.CompatibilityTest',
                            str(root / 'net/minecraft/core/Direction.class')], check=True, capture_output=True)
